  `assist_percentage` decimal(10,4) DEFAULT NULL,
  `steal_percentage` decimal(10,4) DEFAULT NULL,
  `block_percentage` decimal(10,4) DEFAULT NULL,
  `turnover_percentage` decimal(10,4) DEFAULT NULL,
  `usage_percentage` decimal(10,4) DEFAULT NULL,
  `offensive_win_shares` decimal(10,4) DEFAULT NULL,
  `defensive_win_shares` decimal(10,4) DEFAULT NULL,
  `win_shares` decimal(10,4) DEFAULT NULL,
  `win_shares_per_48_minutes` decimal(10,4) DEFAULT NULL,
  `offensive_box_plus_minus` decimal(10,4) DEFAULT NULL,
  `defensive_box_plus_minus` decimal(10,4) DEFAULT NULL,
  `box_plus_minus` decimal(10,4) DEFAULT NULL,
  `value_over_replacement_player` decimal(10,4) DEFAULT NULL,
  PRIMARY KEY (`source_row`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
