--
-- Table structure for table `player_playoff_stats`
--

DROP TABLE IF EXISTS `player_playoff_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_playoff_stats` (
  `playoff_stat_id` int NOT NULL AUTO_INCREMENT,
  `player_id` varchar(20) NOT NULL,
  `team_id` int NOT NULL,
  `season_id` int NOT NULL,
  `games_played` int DEFAULT NULL,
  `games_started` int DEFAULT NULL,
  `minutes_per_game` decimal(6,2) DEFAULT NULL,
  `points_per_game` decimal(6,2) DEFAULT NULL,
  `assists_per_game` decimal(6,2) DEFAULT NULL,
  `rebounds_per_game` decimal(6,2) DEFAULT NULL,
  PRIMARY KEY (`playoff_stat_id`),
  UNIQUE KEY `player_id` (`player_id`,`team_id`,`season_id`),
  KEY `team_id` (`team_id`),
  KEY `season_id` (`season_id`),
  CONSTRAINT `player_playoff_stats_ibfk_1` FOREIGN KEY (`player_id`) REFERENCES `players` (`player_id`),
  CONSTRAINT `player_playoff_stats_ibfk_2` FOREIGN KEY (`team_id`) REFERENCES `teams` (`team_id`),
  CONSTRAINT `player_playoff_stats_ibfk_3` FOREIGN KEY (`season_id`) REFERENCES `seasons` (`season_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2406 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

