--
-- Table structure for table `player_season_stats`
--

DROP TABLE IF EXISTS `player_season_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_season_stats` (
  `stat_id` int NOT NULL AUTO_INCREMENT,
  `player_id` varchar(20) NOT NULL,
  `team_id` int NOT NULL,
  `season_id` int NOT NULL,
  `games_played` int DEFAULT NULL,
  `games_started` int DEFAULT NULL,
  `minutes_played` decimal(8,2) DEFAULT NULL,
  `total_points` int DEFAULT NULL,
  `total_assists` int DEFAULT NULL,
  `total_rebounds` int DEFAULT NULL,
  `points_per_game` decimal(6,2) DEFAULT NULL,
  `assists_per_game` decimal(6,2) DEFAULT NULL,
  `rebounds_per_game` decimal(6,2) DEFAULT NULL,
  `experience` int DEFAULT NULL,
  `is_mvp_candidate` tinyint(1) DEFAULT '0',
  `mvp_rank` int DEFAULT NULL,
  `mvp_points` decimal(8,2) DEFAULT NULL,
  `position_id` int DEFAULT NULL,
  `age` int DEFAULT NULL,
  `steals_per_game` decimal(7,3) DEFAULT NULL,
  `blocks_per_game` decimal(7,3) DEFAULT NULL,
  `three_point_attempts_per_game` decimal(7,3) DEFAULT NULL,
  `field_goal_attempts_per_game` decimal(7,3) DEFAULT NULL,
  `field_goal_percentage` decimal(7,3) DEFAULT NULL,
  PRIMARY KEY (`stat_id`),
  UNIQUE KEY `player_id` (`player_id`,`team_id`,`season_id`),
  KEY `team_id` (`team_id`),
  KEY `season_id` (`season_id`),
  KEY `position_id` (`position_id`),
  CONSTRAINT `player_season_stats_ibfk_1` FOREIGN KEY (`player_id`) REFERENCES `players` (`player_id`),
  CONSTRAINT `player_season_stats_ibfk_2` FOREIGN KEY (`team_id`) REFERENCES `teams` (`team_id`),
