DROP TABLE IF EXISTS `team_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `team_stats` (
  `team_stat_id` int NOT NULL AUTO_INCREMENT,
  `team_id` int NOT NULL,
  `season_id` int NOT NULL,
  `wins` int DEFAULT NULL,
  `losses` int DEFAULT NULL,
  `conference` varchar(20) DEFAULT NULL,
  `made_playoffs` tinyint(1) DEFAULT NULL,
  `is_champion` tinyint(1) DEFAULT '0',
  `average_age` decimal(5,2) DEFAULT NULL,
  `offensive_rating` decimal(6,2) DEFAULT NULL,
  `defensive_rating` decimal(6,2) DEFAULT NULL,
  `net_rating` decimal(6,2) DEFAULT NULL,
  `pace` decimal(6,2) DEFAULT NULL,
  `arena` varchar(150) DEFAULT NULL,
  `attendance` int DEFAULT NULL,
  PRIMARY KEY (`team_stat_id`),
  UNIQUE KEY `team_id` (`team_id`,`season_id`),
  KEY `season_id` (`season_id`),
  CONSTRAINT `team_stats_ibfk_1` FOREIGN KEY (`team_id`) REFERENCES `teams` (`team_id`),
  CONSTRAINT `team_stats_ibfk_2` FOREIGN KEY (`season_id`) REFERENCES `seasons` (`season_id`)
) ENGINE=InnoDB AUTO_INCREMENT=331 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

